        {
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Bu dağların bir rakibi varsa rüzgârdır. rüzgâr burda tek başına bir hükümdardır.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Burda insan duman gibi genişler, büyür. Bu dağlarda ıstıraplar, sevinçler büyür.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Bir dürbünün ters tarafı gibi bu dünya En büyük şey, en asil şey küçülür burda.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Burda yalan para eden biricik iştir, Burda her şey bir yapmacık, bir gösteriştir.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Her büyüklük cüzzam gibi dökülür burda, En muazzam ölüm bile küçülür burda.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Şimdi şiir bence senin yüzündür Şimdi benim tahtım senin dizindir Sevgilim, saadet ikimizindir Göklerden gelen bir yadigar gibi", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Sözün şiirlerin mükemmelidir Senden başkasını seven delidir Yüzün çiçeklerin en güzelidir Gözlerin bilinmez bir diyar gibi", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Başını göğsüme sakla sevgilim Güzel saçlarında dolaşsın elim Bir gün ağlayalım, bir gün gülelim Sevişen yaramaz çocuklar gibi", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Hakikat, sanat, ilim masaldan ibarettir, Aşk iki cins beyninde tutkaldan ibarettir; Gülmeli, kahkayla bunlara gülmelidir.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Hayat ki akıp gider bulanık bir su gibi, Korkulu rüyalarla geçen bir uyku gibi... Çabalama... Kabul et bunu olduğu gibi!", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Hayattan fazla bir şey bekleyenler delidir...", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Meğer ben ne kadar boş şeylere ağlamışım; Kalbim hakikat diye bir ihtimale tapmış.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Ne manasız şeylere meğer bel bağlamışım; Meğer benim peşinde koştuklarım serapmış...", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Kimsede bulamadım menfaatsiz bir yürek; Kadınlar bana yalnız soğuk bir deri verdi.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Anladım insanlardan geldiğini kederin; Uzak, herkesten uzak bir hayat süreceğim.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Bütün güzel laflardan ve hoş insanlardan sıkılan bu mahlukları, birbirlerinin sessiz mevcudiyeti, yorgunluk verecek kadar doyuruyordu.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Yaşam, herkesten daha iyi, herkesten daha üstün yaşamak, insanlara hâkim olarak, kuvvetli, belki de biraz zalim olarak yaşamak...", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Mini mini kafalarımızı ukalaca kitaplar, birbirinden çürük bilgi ler, neticesi olmayan hesaplar ve Allah kahretsin, karmakarışık menfaat düşünceleri dolduruyor...", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Kuvvetli olmak her şeyin fevkindedir. Kuvvet her hareketi mazur gösterebilir. Acizlere acımak ise sersemliktir.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "İyilik demek kimseye kötülüğü dokunmamak değil, kötülük yapacak cevheri içinde taşımamak demektir.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "İçimizdeki şeytan pek de kurnazca olmayan bir kaçamak yolu... İçimizde şeytan yok... İçimizde aciz var... tembellik var...", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "İnsanlar nedense daha ziyade ne bulacaklarını tahmin ettikleri şeyleri araştırmayı tercih ediyorlar.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Bu akşam anladım ki, bir insan diğer bir insana bazan hayata bağlandığından çok daha kuvvetli bağlarla sarılabilirmiş.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Hayatta yalnız kalmanın esas olduğunu hala kabul edemiyor musunuz?", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Hayat ancak bir kere oynanan bir kumardır, ben onu kaybettim. İkinci defa oynayamam...", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Dünyada bana hiçbir şey, tabiattan melül bir insanın zorla gülmeye çalışması kadar acı gelmemiştir.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Kız arkadaşlarım benimle ahbaplık etmeyi ve fikirlerimi kabul etmeyi zevklerine ve rahatlarına aykırı buldular.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Kendimi bildim bileli, bütün günlerimi, haberim olmadan ve nefsime itiraf etmeden, bir insanı aramakla geçirmiş ve bu yüzden bütün diğer insanlardan kaçmıştım.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Bu insanlar dünyada nasıl yaşamak lazımsa öyle yaşıyorlar, vazifelerini yapıyorlar, hayata bir şey ilave ediyorlardı.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "Muhakkak ki dünyanın en lüzumsuz adamıydım. Hayat beni kaybetmekle hiçbir şey ziyan etmeyecekti.", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "İnsanları kendi cinslerinden biri üzerinde kudret ve selahiyetlerini denemek kadar tatlı sarhoş eden ne vardır?", Author = "Sabahattin Ali" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Sabahattin_Ali", Text = "İnsan tahammül edemeyeceğini zannettiği şeylere pek çabuk alışıyor ve katlanıyor.", Author = "Sabahattin Ali" },
